exercises.solutionCode:
String? firstChar(String? text) {
  if (text == null || text.isEmpty) {
    return null;
  }
  return text[0];
}

void main() {
  print(firstChar('Hello'));
  print(firstChar(null));
  print(firstChar(''));
}

