exercises.solutionCode:
int? parseIntSafe(String? text) {
  if (text == null) {
    return null;
  }

  return int.tryParse(text);
}

void main() {
  print(parseIntSafe('123'));
  print(parseIntSafe(null));
  print(parseIntSafe('abc'));
}
